export const getCategory = (slug) => categories.find((c) => c.slug === slug)
export const getTemplate = (id) => templates.find((t) => t.id === id)
export const countIn = (slug) => templates.filter((t) => t.category === slug).length

// Paths are relative so they work under any base URL.
export const asset = (id, file) => `templates/${id}/${file}`
export const liveUrl = (id, page = 'index') => `templates/${id}/${page}.html`
export const getPages = (id) => pages[id] || [['index', 'Home']]
